/* version:3*/
const propstToReset = ['item_behavior', 'data_source', 'stored_length', 'prec', 'scale'];
const val = [];
for (let i = 0; i < propstToReset.length; i++) {
	val[propstToReset[i]] = getRelationshipProperty(relationshipID, propstToReset[i]);
}

function resetRelationshipProperties(resetArr) {
	for (let i = 0; i < propstToReset.length; i++) {
		if (val[propstToReset[i]] !== '') {
			for (let j = 0; j < resetArr.length; j++) {
				if (resetArr[j] == propstToReset[i]) {
					setRelationshipProperty(relationshipID, propstToReset[i], '');
					resetArr.splice(j, 1);
					break;
				}
			}
		}
	}
}

const newDataType = getRelationshipProperty(relationshipID, 'data_type');
if (newDataType == 'string') {
	resetRelationshipProperties(['item_behavior', 'data_source', 'prec', 'scale']);
} else if ((newDataType == 'float') || (newDataType == 'decimal')) {
	resetRelationshipProperties(['item_behavior', 'data_source', 'stored_length']);
} else if ((newDataType == 'list') || (newDataType == 'filter list') || (newDataType == 'color list') || (newDataType == 'sequence') ||
	(newDataType == 'item') || (newDataType == 'foreign')) {
	resetRelationshipProperties(['data_source', 'stored_length', 'prec', 'scale']);
} else {
	resetRelationshipProperties(['item_behavior', 'data_source', 'stored_length', 'prec', 'scale']);
}

return true;
